const crypto = require('crypto');
const raw = $input.first().json.body || '';
const sig = $input.first().json.headers?.['x-documenso-signature'] || '';
const secret = $env.DOCUMENSO_WEBHOOK_SECRET || '';
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
const ok = crypto.timingSafeEqual(Buffer.from(sig.padEnd(64, '0').slice(0, 64), 'hex'), Buffer.from(expected.slice(0, 64), 'hex'));
if (!ok) {
  return [{ json: { invalid: true } }];
}

const body = JSON.parse(raw);
return [{ json: {
  invalid: false,
  event: body.event,
  envelope_id: body.payload?.id,
  proposal_ref: body.payload?.title,
  lead_id: parseInt((body.payload?.title || '').replace(/^UW-/, '').split('-')[0], 10) || null,
  signed_at: body.payload?.signedAt
} }];
